304	    /**
305	     * Return the owners that already share this owner's household, i.e. resolve to the same
306	     * deterministic {@link #householdIdFor(Owner) householdId} (same normalized last name and
307	     * postcode).
308	     */
309	    private List<Owner> householdMembers(Owner owner) {
310	        String householdId = householdIdFor(owner);
311	        List<Owner> members = new java.util.ArrayList<>();
312	        for (Owner existing : this.clinicService.findAllOwners()) {
313	            if (householdId.equals(householdIdFor(existing))) {
314	                members.add(existing);
315	            }
316	        }
317	        return members;
318	    }
319	
320	    /**
321	     * Return {@code true} when another owner already shares this owner's household, i.e. resolves to
322	     * the same deterministic {@link #householdIdFor(Owner) householdId}.
323	     */
324	    private boolean sharesHouseholdWithExisting(Owner owner) {
325	        return !householdMembers(owner).isEmpty();
326	    }
