617	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
618	        if (currentOwner != null) {
619	            Pet currentPet = this.clinicService.findPetById(petId);
620	            if (currentPet != null) {
621	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
622	                currentPet.setName(petFieldsDto.getName());
